$content = Get-Content 'backend/src/controllers/productionRoutingController.js' -Raw\n\n# Remove the validateHeader method\n$pattern = '  validateHeader\\(header\\) \\{[\\s\\S]*?return null;\\s*\\}\\s*\\n'\n$content = $content -replace $pattern, \"`n\"\n\n# Remove the calls to validateHeader in create method\n$pattern2 = '      const headerError = this\\.validateHeader\\(header\\);\\s*if \\(headerError\\) \\{\\s*await connection\\.rollback\\(\\);\\s*return res\\.status\\(400\\)\\.json\\(\\{ success: false, error: headerError \\}\\);\\s*\\}\\s*\\n'\n$content = $content -replace $pattern2, \"\"\n\nSet-Content 'backend/src/controllers/productionRoutingController.js' $content -NoNewline\nWrite-Host 'Done!'"